<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><h4>Purchases</h4><?php if(session()->getFlashdata('success')):?><div class="alert alert-success"><?=session()->getFlashdata('success')?></div><?php endif;?><?php if(session()->getFlashdata('error')):?><div class="alert alert-danger"><?=esc(session()->getFlashdata('error'))?></div><?php endif;?><form method="post" action="<?=site_url('purchases/save')?>"><?=csrf_field()?><input type="hidden" name="lines_json" id="lines_json"><input type="hidden" name="payments_json" id="payments_json"><div class="row g-3"><div class="col-md-6"><label class="form-label">Supplier</label><select name="supplier_id" class="form-select" required><option value="">Select</option><?php foreach($suppliers as $s):?><option value="<?=$s['id']?>"><?=esc($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Discount</label><input name="discount_amount" id="discount" class="form-control" type="number" step=".01" min="0" value="0"></div></div><div class="card mt-3"><div class="card-body"><div id="lines"></div><button type="button" class="btn btn-outline-primary" id="add">Add line</button><span class="ms-3 fw-bold">Total Rs. <span id="total">0.00</span></span></div></div><div class="card mt-3"><div class="card-body"><div id="payments"></div><button type="button" class="btn btn-outline-secondary" id="pay">Add payment</button><textarea name="notes" class="form-control mt-3" placeholder="Notes"></textarea><button class="btn btn-primary mt-3">Post Purchase</button></div></div></form><script>const types=<?=json_encode($types)?>;function add(){let d=document.createElement('div');d.className='row g-2 mb-2 line';d.innerHTML='<div class="col-md-3"><select class="form-select type"><option value="gas_kg">Gas KG</option><option value="filled_cylinder">Filled cylinder</option><option value="empty_cylinder">Empty cylinder</option></select></div><div class="col-md-3"><select class="form-select cyl"><option value="">—</option>'+types.map(t=>'<option value="'+t.id+'">'+t.code+' — '+t.name+'</option>').join('')+'</select></div><div class="col-md-2"><input class="form-control qty" type="number" min=".001" step=".001" value="1"></div><div class="col-md-2"><input class="form-control actual" type="number" min="0" step=".001" placeholder="Actual kg (filled only)"></div><div class="col-md-2"><input class="form-control rate" type="number" min="0" step=".0001" value="0"></div><div class="col-md-1 lineTotal">0</div><div class="col-md-1"><button type="button" class="btn btn-outline-danger rm">×</button></div>';document.getElementById('lines').append(d);d.querySelector('.rm').onclick=()=>{d.remove();calc()};d.querySelectorAll('input,select').forEach(e=>e.oninput=calc)}function calc(){let t=0;document.querySelectorAll('.line').forEach(d=>{let x=+d.querySelector('.qty').value*+d.querySelector('.rate').value;d.querySelector('.lineTotal').textContent=x.toFixed(2);t+=x});t-=+document.getElementById('discount').value;document.getElementById('total').textContent=Math.max(0,t).toFixed(2)}function pay(){let d=document.createElement('div');d.className='row g-2 mb-2 payment';d.innerHTML='<div class="col-md-3"><select class="form-select mode"><option>cash</option><option>cheque</option><option>online</option><option>credit</option></select></div><div class="col-md-3"><input class="form-control amount" type="number" min=".01" step=".01" placeholder="Amount"></div><div class="col-md-4"><input class="form-control ref" placeholder="Reference"></div>';document.getElementById('payments').append(d)}document.getElementById('add').onclick=add;document.getElementById('pay').onclick=pay;document.getElementById('discount').oninput=calc;document.querySelector('form').onsubmit=()=>{let ls=[...document.querySelectorAll('.line')].map(d=>({line_type:d.querySelector('.type').value,cylinder_type_id:d.querySelector('.cyl').value,quantity:d.querySelector('.qty').value,unit_rate:d.querySelector('.rate').value,actual_gas_weight_kg:d.querySelector('.actual').value}));let ps=[...document.querySelectorAll('.payment')].map(d=>({payment_mode:d.querySelector('.mode').value,amount:d.querySelector('.amount').value,reference_no:d.querySelector('.ref').value}));if(!ls.length||!ps.length){alert('Add line and payment');return false}document.getElementById('lines_json').value=JSON.stringify(ls);document.getElementById('payments_json').value=JSON.stringify(ps);return true};add();pay();</script><?= $this->endSection() ?>